import{_ as n,o as t,c as o,ah as s}from"./chunks/framework.C-FRNfAJ.js";const g=JSON.parse('{"title":"Inscription et convention","description":"","frontmatter":{"layout":"doc"},"headers":[],"relativePath":"guide/apprenant/inscription.md","filePath":"src/guide/apprenant/inscription.md"}'),r={name:"guide/apprenant/inscription.md"};function a(i,e,l,u,c,p){return t(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="inscription-et-convention" tabindex="-1">Inscription et convention <a class="header-anchor" href="#inscription-et-convention" aria-label="Permalink to &quot;Inscription et convention&quot;">​</a></h1><p>À la décision « admis », Kura crée votre <strong>inscription</strong>. Elle reste « en attente de signature » tant que vous n&#39;avez pas signé votre convention de formation. Tout se passe dans <strong>Parcours → Mon inscription</strong>.</p><h2 id="completer-son-dossier" tabindex="-1">Compléter son dossier <a class="header-anchor" href="#completer-son-dossier" aria-label="Permalink to &quot;Compléter son dossier&quot;">​</a></h2><p>Avant de pouvoir signer, trois choses doivent être en place. La page <strong>Mon inscription</strong> liste ce qui manque.</p><h3 id="une-cohorte" tabindex="-1">Une cohorte <a class="header-anchor" href="#une-cohorte" aria-label="Permalink to &quot;Une cohorte&quot;">​</a></h3><p>Votre <strong>cohorte</strong> est la session que vous suivrez, avec ses dates de début et de fin. Elle est choisie par le conseiller à l&#39;admission, ou, à défaut, par le Coordinateur pédagogique, qui vous prévient par e-mail. Vous ne la choisissez pas vous-même.</p><h3 id="un-format" tabindex="-1">Un format <a class="header-anchor" href="#un-format" aria-label="Permalink to &quot;Un format&quot;">​</a></h3><p>Vous confirmez ou changez votre <strong>format</strong> (distanciel, hybride, présentiel) parmi ceux que propose la cohorte, avec leur prix. Vous pouvez le modifier <strong>jusqu&#39;à la signature</strong> de la convention ; il est ensuite figé.</p><h3 id="deux-consentements" tabindex="-1">Deux consentements <a class="header-anchor" href="#deux-consentements" aria-label="Permalink to &quot;Deux consentements&quot;">​</a></h3><p>Répondez à chacun <strong>séparément</strong> (« J&#39;accepte » ou « Je refuse ») :</p><ul><li><strong>Réutilisation pédagogique du projet tutoré</strong> : NextBoxx peut réutiliser à des fins pédagogiques le projet que vous réalisez pendant la formation ;</li><li><strong>Droit à l&#39;image</strong> : NextBoxx peut vous montrer dans ses enregistrements.</li></ul><p>Les deux réponses sont obligatoires pour signer, mais rien ne vous oblige à accepter. Vous pouvez changer d&#39;avis <strong>à tout moment</strong> ; chaque changement est enregistré. Un refus est respecté partout : l&#39;équipe voit dans la fiche de la cohorte quels apprenants n&#39;ont pas donné leur droit à l&#39;image et ne diffuse aucun enregistrement où vous apparaissez.</p><h2 id="signer-la-convention" tabindex="-1">Signer la convention <a class="header-anchor" href="#signer-la-convention" aria-label="Permalink to &quot;Signer la convention&quot;">​</a></h2><p>Quand le dossier est complet, Kura vous envoie un message et la page <strong>Mon inscription</strong> affiche « Votre convention est prête ».</p><ol><li>Cliquez sur <strong>Lire la convention</strong>. Elle comprend le texte des conditions générales, puis les conditions particulières : les parties, la formation, la cohorte, le format, le <strong>prix hors taxe</strong> et l&#39;<strong>échéancier</strong> des trois paiements avec leurs dates.</li><li>Faites défiler jusqu&#39;au bout : la case « J&#39;ai lu la convention jusqu&#39;au bout et j&#39;en accepte les termes » ne s&#39;active qu&#39;ensuite.</li><li>Cliquez sur <strong>Recevoir un code</strong>. Un code à <strong>6 chiffres</strong> est envoyé à votre adresse e-mail. Il est valable <strong>15 minutes</strong>, ne sert qu&#39;une fois, et vous avez 5 essais.</li><li>Saisissez le code et cliquez sur <strong>Signer la convention</strong>.</li></ol><p>Votre convention est alors « en attente de contre-signature » : l&#39;équipe pédagogique contre-signe pour edPage group (automatiquement ou à la main, selon le réglage retenu). Vous recevez ensuite le PDF scellé par e-mail ; il est aussi dans <strong>Mes documents</strong>, sous la référence <code>CONV-NB-AAAA-XXX</code>.</p><p>À la contre-signature, votre inscription devient <strong>active</strong>, et le <strong>format, la cohorte et le prix sont figés</strong>. La première facture est émise (voir <a href="./paiements.html">Paiements</a>).</p><h2 id="si-vous-etes-mineur" tabindex="-1">Si vous êtes mineur <a class="header-anchor" href="#si-vous-etes-mineur" aria-label="Permalink to &quot;Si vous êtes mineur&quot;">​</a></h2><p>Pour un apprenant mineur, c&#39;est le <strong>représentant légal</strong> qui consent et qui signe, sans avoir besoin de compte Kura :</p><ol><li>Dans <strong>Mon inscription</strong>, rubrique « Représentant légal », saisissez son nom complet et son adresse e-mail, puis <strong>Envoyer le lien</strong>.</li><li>Il reçoit un lien pour donner les deux consentements. Le lien est valable <strong>7 jours</strong> et ne sert qu&#39;une fois ; <strong>Envoyer un nouveau lien</strong> remplace le précédent.</li><li>Quand le dossier est complet, vous lui envoyez la convention avec <strong>Envoyer la convention à mon représentant</strong>. Il la lit, reçoit un code à 6 chiffres à sa propre adresse et signe depuis un second lien, valable 7 jours.</li></ol><p>Seuls comptent les consentements et la signature du représentant légal.</p><h2 id="quand-vous-etes-finance-par-une-entreprise" tabindex="-1">Quand vous êtes financé par une entreprise <a class="header-anchor" href="#quand-vous-etes-finance-par-une-entreprise" aria-label="Permalink to &quot;Quand vous êtes financé par une entreprise&quot;">​</a></h2><p>Si une entreprise finance une part de votre formation, le Coordinateur l&#39;indique <strong>avant la signature</strong>. La convention en reprend la répartition (par exemple 60 % apprenant, 40 % financeur) et chaque échéance est facturée à chacun pour sa part.</p><p>Une <strong>convention tripartite</strong> est en plus préparée à la contre-signature de votre convention. Elle reprend les mêmes mentions ; c&#39;est le financeur qui la signe, depuis son espace « Apprenants financés ». Elle ne bloque ni votre inscription ni la facturation. Vous en recevez le PDF une fois qu&#39;elle est signée par les deux parties.</p><h2 id="si-votre-cohorte-change" tabindex="-1">Si votre cohorte change <a class="header-anchor" href="#si-votre-cohorte-change" aria-label="Permalink to &quot;Si votre cohorte change&quot;">​</a></h2><p>Tout changement de cohorte après la signature (report décidé par NextBoxx, force majeure) <strong>remplace la convention</strong> :</p><ul><li>l&#39;ancienne est conservée, marquée « remplacée » ;</li><li>votre inscription repasse en attente de signature ;</li><li>une nouvelle convention, <strong>au même prix et au même format</strong>, vous est proposée. Vous êtes prévenu par e-mail.</li></ul><p>Ce que vous avez déjà payé est conservé et déduit des tranches de la nouvelle convention.</p>',28)])])}const m=n(r,[["render",a]]);export{g as __pageData,m as default};
